import {
  Link,
  Outlet,
  createFileRoute,
  redirect,
  useLocation,
  useRouter,
} from '@tanstack/react-router'
import { ChevronDown, LogOut } from 'lucide-react'

import { Button } from '#/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '#/components/ui/dropdown-menu'
import { authClient } from '#/lib/auth-client'

// Pathless layout: every route under src/routes/_app/ requires a session
// and renders inside the app shell (top bar + page).
export const Route = createFileRoute('/_app')({
  beforeLoad: ({ context }) => {
    if (!context.user) throw redirect({ to: '/login' })
    return { user: context.user }
  },
  component: AppShell,
})

// Top-bar navigation. `admin: true` hides the item from non-admins;
// the route itself must still guard access. `also` marks the item active under
// other path prefixes too (book pages belong to the Library).
const navItems = [
  { to: '/', label: 'Library', exact: true, also: '/books/' },
  { to: '/market', label: 'Market', admin: true },
  { to: '/settings', label: 'Settings' },
] as const

function AppShell() {
  const { user } = Route.useRouteContext()
  const router = useRouter()
  const pathname = useLocation({ select: (location) => location.pathname })

  async function signOut() {
    await authClient.signOut()
    await router.invalidate()
  }

  return (
    <div className="min-h-screen">
      <header className="border-b">
        <div className="mx-auto flex h-14 max-w-6xl items-center gap-8 px-4">
          <Link to="/" className="font-semibold">
            Bookserve
          </Link>
          <nav className="flex items-center gap-6 text-sm">
            {navItems
              .filter((item) => !('admin' in item) || user.role === 'admin')
              .map((item) => (
                <Link
                  key={item.to}
                  to={item.to}
                  activeOptions={{ exact: 'exact' in item }}
                  data-also-active={
                    'also' in item && pathname.startsWith(item.also)
                      ? true
                      : undefined
                  }
                  className="text-muted-foreground transition-colors hover:text-foreground data-[also-active]:font-medium data-[also-active]:text-foreground data-[status=active]:font-medium data-[status=active]:text-foreground"
                >
                  {item.label}
                </Link>
              ))}
          </nav>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" className="ml-auto">
                {user.username}
                <ChevronDown />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onSelect={signOut}>
                <LogOut />
                Sign out
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>
      <Outlet />
    </div>
  )
}
import { useState } from 'react'

import { cn } from '#/lib/utils'

type Props = {
  title: string
  authors: string[]
  coverUrl: string | null
  className?: string
}

// A stable hue per title, so a placeholder keeps its color between visits.
function hue(text: string) {
  let h = 0
  for (const char of text) h = (h * 31 + char.charCodeAt(0)) % 360
  return h
}

// The cover image, or a tinted block with the title for books without one
// (or whose image fails to load).
export function BookCover({ title, authors, coverUrl, className }: Props) {
  const [failed, setFailed] = useState<string | null>(null)
  const base = cn(
    'aspect-[2/3] w-full overflow-hidden rounded-md shadow-sm ring-1 ring-black/5',
    className,
  )
  if (coverUrl && failed !== coverUrl) {
    return (
      <img
        src={coverUrl}
        alt={title}
        loading="lazy"
        onError={() => setFailed(coverUrl)}
        className={cn(base, 'bg-muted object-cover')}
      />
    )
  }
  const h = hue(title)
  return (
    <div
      className={cn(
        base,
        '@container flex flex-col justify-between p-3 text-left',
      )}
      style={{
        backgroundColor: `oklch(0.9 0.05 ${h})`,
        color: `oklch(0.32 0.07 ${h})`,
      }}
    >
