  detail,
}: {
  book: T
  admin: boolean
  detail?: (book: T) => string
}) {
  const body = (
    <>
      <div className="relative">
        <BookCover
          {...book}
          className="transition-shadow group-hover:shadow-md"
        />
        {book.libraryId && (
          <span
