import { cn } from '#/lib/utils'

// A book's blurb set like book prose: serif, indented paragraphs, and a drop
// cap when it opens with a letter (not a quote mark or "#1 bestseller").
export function BookDescription({
  text,
  className,
}: {
  text: string
  className?: string
}) {
  const paragraphs = text
    .split(/\n\s*\n|\n/)
    .map((p) => p.trim())
    .filter(Boolean)
  const dropCap = /^\p{L}/u.test(paragraphs[0] ?? '')
  return (
    <div
      className={cn(
        'max-w-prose font-serif text-base leading-relaxed text-pretty hyphens-auto',
        className,
      )}
    >
      {paragraphs.map((p, i) => (
        <p
          key={i}
          className={cn(
            'not-first:indent-6',
            i === 0 &&
              dropCap &&
              'first-letter:float-left first-letter:mt-1 first-letter:mr-2 first-letter:text-[3.25rem] first-letter:leading-[0.8] first-letter:font-semibold first-letter:text-primary',
          )}
        >
          {p}
        </p>
      ))}
    </div>
  )
}

